INSERT INTO providers (provider_id,provider_name,category_id,service_description,service_tags,location,qualifications,contact_email,verification_status,created_at) VALUES
(1,'Mapenzi Birth Practice',5,'Prenatal Care in Nairobi. We provide blood pressure screening and pregnancy monitoring for families, with expectant mother and antenatal check-up delivered through online consultation. Our practice focuses on prenatal, and routine clinical monitoring and check-ups during pregnancy. Services are offered in English and Kiswahili.','antenatal-check-up,blood-pressure-screening,expectant-mother,pregnancy-monitoring,prenatal-care','Kikuyu','Diploma in midwifery, licensed by the Nursing Council','info@mapenzibirthpractice.example.co.ke','verified','2026-06-07 00:00:00'),
(2,'Wema Birth Practice',5,'Prenatal Care in Nairobi. We provide foetal growth scan and trimester for families, with expectant mother and gestational delivered through group sessions. Our practice focuses on prenatal, and routine clinical monitoring and check-ups during pregnancy. Services are offered in English and Kiswahili.','expectant-mother,foetal-growth-scan,gestational,prenatal-care,trimester','Kileleshwa','Registered nurse-midwife, 8 years in maternity care','info@wemabirthpractice.example.co.ke','verified','2026-01-10 00:00:00'),
(3,'Heri Maternity Centre',5,'Prenatal Care in Nairobi. We provide expectant mother and gestational for families, with prenatal and foetal growth scan delivered through group sessions. Our practice focuses on antenatal check-up, and routine clinical monitoring and check-ups during pregnancy. Services are offered in English and Kiswahili.','expectant-mother,foetal-growth-scan,gestational,prenatal,prenatal-care','South C','MBChB with postgraduate training in obstetrics','info@herimaternitycentre.example.co.ke','verified','2026-01-24 00:00:00'),
(4,'Subira Pregnancy Care Hub',5,'Prenatal Care in Nairobi. We provide foetal growth scan and prenatal for families, with expectant mother and blood pressure screening delivered through weekend availability. Our practice focuses on antenatal check-up, and routine clinical monitoring and check-ups during pregnancy. Services are offered in English and Kiswahili.','blood-pressure-screening,expectant-mother,foetal-growth-scan,prenatal,prenatal-care','Kikuyu','Diploma in midwifery, licensed by the Nursing Council','info@subirapregnancycarehub.example.co.ke','verified','2026-02-19 00:00:00'),
(5,'Taifa Maternity Centre',5,'Prenatal Care in Nairobi. We provide expectant mother and prenatal for families, with trimester and gestational delivered through home visits. Our practice focuses on pregnancy monitoring, and routine clinical monitoring and check-ups during pregnancy. Services are offered in English and Kiswahili.','expectant-mother,gestational,prenatal,prenatal-care,trimester','Langata','Registered nurse-midwife, 8 years in maternity care','info@taifamaternitycentre.example.co.ke','verified','2026-01-31 00:00:00'),
(6,'Pendo Pregnancy Care Hub',5,'Prenatal Care in Nairobi. We provide pregnancy monitoring and gestational for families, with expectant mother and prenatal delivered through walk-in clinic. Our practice focuses on trimester, and routine clinical monitoring and check-ups during pregnancy. Services are offered in English and Kiswahili.','expectant-mother,gestational,pregnancy-monitoring,prenatal,prenatal-care','Lavington','MBChB with postgraduate training in obstetrics','info@pendopregnancycarehub.example.co.ke','verified','2026-01-08 00:00:00'),
(7,'Nuru Maternity Centre',5,'Prenatal Care in Nairobi. We provide antenatal check-up and blood pressure screening for families, with gestational and prenatal delivered through weekend availability. Our practice focuses on expectant mother, and routine clinical monitoring and check-ups during pregnancy. Services are offered in English and Kiswahili.','antenatal-check-up,blood-pressure-screening,gestational,prenatal,prenatal-care','Buruburu','Certified childbirth educator, 6 years practice','info@nurumaternitycentre.example.co.ke','verified','2026-01-17 00:00:00'),
(8,'Wema Pregnancy Care Hub',6,'Antenatal Classes in Nairobi. We provide antenatal class and birth plan for families, with partner support and expectant parents delivered through one-to-one sessions. Our practice focuses on breathing techniques, and group and private classes preparing parents for labour and newborn care. Services are offered in English, Kiswahili and Somali.','antenatal-class,antenatal-classes,birth-plan,expectant-parents,partner-support','Kileleshwa','Certified childbirth educator, 6 years practice','info@wemapregnancycarehub.example.co.ke','verified','2026-06-19 00:00:00'),
(9,'Malaika Birth Practice',6,'Antenatal Classes in Nairobi. We provide expectant parents and partner support for families, with breathing techniques and childbirth education delivered through evening appointments. Our practice focuses on newborn care basics, and group and private classes preparing parents for labour and newborn care. Services are offered in English, Kiswahili and Kikuyu.','antenatal-classes,breathing-techniques,childbirth-education,expectant-parents,partner-support','Kikuyu','Diploma in midwifery, licensed by the Nursing Council','info@malaikabirthpractice.example.co.ke','verified','2026-01-29 00:00:00'),
(10,'Rehema Maternity Centre',6,'Antenatal Classes in Nairobi. We provide antenatal class and labour preparation for families, with newborn care basics and birth plan delivered through evening appointments. Our practice focuses on childbirth education, and group and private classes preparing parents for labour and newborn care. Services are offered in English and Kiswahili.','antenatal-class,antenatal-classes,birth-plan,labour-preparation,newborn-care-basics','Runda','Registered nurse-midwife, 8 years in maternity care','info@rehemamaternitycentre.example.co.ke','rejected','2026-02-16 00:00:00'),
